	YY_BREAK
case 4:
YY_RULE_SETUP
{ BEGIN MULTI_LINE_COMMENT; }
	YY_BREAK
case 5:
YY_RULE_SETUP
{ BEGIN INITIAL; }
	YY_BREAK
case 6:
